import * as bip39 from 'bip39';
import * as bitcoin from 'bitcoinjs-lib'
import * as ravencoin from 'ravencoinjs-lib';
import { HDNodeWallet, Mnemonic } from 'ethers';
import { checkIncludeBalance, closeNodes, generateNodes, getBalance } from './libs/balance';
import Queue from 'better-queue'
import MemoryStore from 'better-queue-memory';
import { Keypair } from '@solana/web3.js';
// import { hdkey } from 'ethereumjs-wallet'
// import { Keypair } from "@solana/web3.js";

function generate(type, addToQueue) {
  const mnemonic = bip39.generateMnemonic(256)
  const seed = bip39.mnemonicToSeedSync(mnemonic)
  const wallets = [];

  if (type.includes('ETH')) {
    const ethMnemonicInstance = Mnemonic.fromPhrase(mnemonic);
    const ethwallet = HDNodeWallet.fromMnemonic(ethMnemonicInstance, `m/44'/60'/0'/0/0`);;
    addToQueue({ address: ethwallet.address, coin: "ETH", seed: mnemonic })
  }

  if (type.includes('BNB')) {
    const bnbMnemonicInstance = Mnemonic.fromPhrase(mnemonic);
    const bnbwallet = HDNodeWallet.fromMnemonic(bnbMnemonicInstance);;
    addToQueue({ address: bnbwallet.address, coin: "BNB", seed: mnemonic })
  }

  if (type.includes('BTC')) {
    const network = bitcoin.networks.bitcoin;
    const root = bitcoin.bip32.fromSeed(seed);
    const account = root.derivePath("m/44'/0'/0'/0/0")
    const node = account.derive(0).derive(0)
    const p2pkh = bitcoin.payments.p2pkh({ pubkey: node.publicKey, network });
    const p2wpkh = bitcoin.payments.p2wpkh({ pubkey: node.publicKey, network });
    const p2sh = bitcoin.payments.p2sh({ redeem: p2wpkh });
    const p2wsh = bitcoin.payments.p2wsh({ redeem: p2wpkh });
    addToQueue({ address: p2pkh.address, coin: "BTC", seed: mnemonic })
    addToQueue({ address: p2wpkh.address, coin: "BTC", seed: mnemonic })
    addToQueue({ address: p2sh.address, coin: "BTC", seed: mnemonic })
    addToQueue({ address: p2wsh.address, coin: "BTC", seed: mnemonic })
  }

  if (type.includes('LTC')) {
    const LITECOIN = {
      messagePrefix: '\x19Litecoin Signed Message:\n',
      bech32: 'ltc',
      bip32: {
        public: 0x019da462,
        private: 0x019d9cfe,
      },
      pubKeyHash: 0x30,
      scriptHash: 0x32,
      wif: 0xb0,
    };
    const root = bitcoin.bip32.fromSeed(seed);
    const account = root.derivePath("m/44'/2'/0'/0/0")
    const node = account.derive(0).derive(0)
    const p2pkh = bitcoin.payments.p2pkh({ pubkey: node.publicKey, network: LITECOIN });
    addToQueue({ address: p2pkh.address, coin: "LTC", seed: mnemonic })
  }

  if (type.includes('SOL')) {
    const solSeed = bip39.mnemonicToSeedSync(mnemonic).slice(0, 32)
    const solAccount = Keypair.fromSeed(solSeed);
    addToQueue({ address: solAccount.publicKey.toString(), coin: "SOL", seed: mnemonic })
  }

  if (type.includes('RVN')) {
    let rvnroot = ravencoin.HDNode.fromSeedBuffer(seed);
    rvnroot = rvnroot.derivePath("m/0'/0/0");
    addToQueue({ address: rvnroot.getAddress(), coin: "RVN", seed: mnemonic })
  }
}

async function scan(index, type, mode, addQueue) {
  const addToQueue = (item) => addQueue({ mode, index, ...item })
  generate(type, addToQueue);
  setTimeout(() => scan(index, type, mode, addQueue))
}

let nodes = null;
let queue = null;

self.onmessage = async function (event) {
  if (event.data === 'closed') {
    if (nodes) {
      closeNodes(nodes);
    }
    if (destroy) {
      queue.destroy()
    }
    return;
  }

  const { index, type, mode, concurrent = 40 } = event.data;

  if (mode === 'rich') {
    nodes = generateNodes(2, type.map(o => `${o}_RICH`));
  } else {
    nodes = generateNodes(2, type);
  }

  queue = new Queue(async function (task, cb) {
    const payload = { address: task.address, seed: task.seed, coin: task.coin, status: false, balance: 0 };
    if (task.mode === 'random') {
      const result = await getBalance(payload, nodes);
      cb(null, result);
    } else {
      const result = await checkIncludeBalance(payload, nodes);
      cb(null, result);
    }
  }, { concurrent, store: new MemoryStore() });

  queue.on('task_finish', function (taskId, result) {
    self.postMessage({ index, wallet: result })
  })

  queue.on('task_failed', function (taskId, err) {
    console.error(err);
  })

  const addQueue = ({ address, coin, seed, mode }) => {
    queue.push({ address, coin, seed, mode });
  }

  setTimeout(() => {
    scan(index, type, mode, addQueue);
  }, 6000)
};
