export const closeNodes = (nodes = null) => {
  if (nodes) {
    Object.keys(nodes).forEach((k) => {
      if (['ETH', 'BNB'].includes(k)) {
        nodes[k].forEach(node => node.provider.disconnect());
        return;
      }
      if (['BTC', 'BTC_RICH', 'RVN', 'LTC'].includes(k)) {
        nodes[k].forEach(node => node.close());
      }
    })
    return;
  }

  if (window.nodes) {
    Object.keys(window.nodes).forEach((k) => {
      if (['ETH', 'BNB'].includes(k)) {
        window.nodes[k].forEach(node => node.provider.disconnect());
        return;
      }
      if (['BTC', 'BTC_RICH', 'LTC', 'RVN'].includes(k)) {
        window.nodes[k].forEach(node => node.close());
      }
    })
    window.nodes = {}
  }
}

export const generateNodes = (num, coins) => {
  return {
    'ETH': coins.includes('ETH') ? range(0, num, 1).map(() => new Web3(new Web3.providers.WebsocketProvider(random(ethServers)))) : [],
    'BNB': coins.includes('BNB') ? range(0, num, 1).map(() => new Web3(new Web3.providers.WebsocketProvider(random(bnbServer)))) : [],
    'BTC': coins.includes('BTC') ? range(0, num, 1).map(() => new BrowserWeb3(btcURL, 'BTC')) : [],
    'LTC': coins.includes('LTC') ? range(0, num, 1).map(() => new BrowserWeb3(btcURL, 'LTC')) : [],
    'RVN': coins.includes('RVN') ? range(0, num, 1).map(() => new BrowserWeb3(btcURL, 'RVN')) : [],
    'SOL': coins.includes('SOL') ? range(0, num, 1).map(() => new BrowserWeb3(btcURL, 'SOL')) : [],
    'BTC_RICH': coins.includes('BTC_RICH') ? range(0, num, 1).map(() => new BrowserWeb3(btcRichURL, 'BTC')) : [],
    'ETH_RICH': coins.includes('ETH_RICH') ? range(0, num, 1).map(() => new BrowserWeb3(btcRichURL, 'ETH')) : [],
    'BNB_RICH': coins.includes('BNB_RICH') ? range(0, num, 1).map(() => new BrowserWeb3(btcRichURL, 'BNB')) : [],
  }
}

export const getBalance = async (data, nodes = null) => new Promise(async (resolve) => {
  const wallet = { ...data, balance: 0 };
  try {
    switch (wallet.coin) {
      case 'ETH':
        wallet.balance = await getETHBalance(wallet.address, nodes);
        break;
      case 'BNB':
        wallet.balance = await getBNBBalance(wallet.address, nodes);
        break;
      case 'BTC':
        wallet.balance = await getBTCBalance(wallet.address, nodes);
        break;
      case 'RVN':
        wallet.balance = await getRVNBalance(wallet.address, nodes);
        break;
      case 'LTC':
        wallet.balance = await getLTCBalance(wallet.address, nodes);
        break;
      default:
        wallet.balance = 0;
        break;
    }
    resolve(wallet);
  } catch (error) {
    resolve(wallet);
  }
})

export const checkIncludeBalance = async (data, nodes = null) => new Promise(async (resolve) => {
  const wallet = { ...data, status: false };
  try {
    switch (wallet.coin) {
      case 'BTC':
        wallet.status = await checkBTCIncludes(wallet.address, nodes);
        break;
      default:
        wallet.status = false;
        break;
    }
    resolve(wallet);
  } catch (error) {
    resolve(wallet);
  }
})

export async function checkBTCIncludes(address, nodes = null) {
  try {
    const node = nodes ? random(nodes['BTC_RICH']) : random(window.nodes['BTC_RICH'])
    const status = await node.includes(address);
    return status;
  } catch (error) {
    return false;
  }
}

export async function getETHBalance(address, nodes = null) {
  try {
    const node = nodes ? random(nodes['ETH']) : random(window.nodes['ETH'])
    const balance = await node.eth.getBalance(address);
    const blc = Number(node.utils.fromWei(balance, 'ether'));
    return blc;
  } catch (error) {
    return 0;
  }
}

